mount() {
const api = parent.SONNA_API;
if (!api) return this.setState({ msg: 'Server API unavailable.' });
Promise.all([api('GET', '/api/session'), api('GET', '/api/admin/deposits')]).then((r) => {
if (r[0]._status !== 200 || r[1]._status !== 200) return this.setState({ msg: 'Could not load live SePay status or deposit history.' });
this.setState({ payment: r[0].payment || {}, simTopup: !!r[0].simTopup, cardTopupReady: !!r[0].cardTopupReady, deposits: r[1].deposits || [], msg: '' });
}).catch(() => this.setState({ msg: 'Connection to server failed.' }));
}
renderVals() {
const on = '#FF8A1F', off = '#A3ACC4';
const st = this.state;
const nav = [
{ label: 'Tá»•ng quan', href: 'AdminDashboard.dc.html' },
