].map((n) => ({ ...n, bg: n.active ? '#1F2538' : 'transparent', fg: n.active ? on : off }));

const num = (s) => parseInt(String(s).replace(/\D/g, ''), 10) || 0;
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'â‚«';
const amt = num(st.amount);
const min = num(st.min);
const cap = num(st.cap);
const pct = parseFloat(String(st.pct).replace(',', '.')) || 0;
let bonus = 0;
let note = 'KhÃ¡ch nháº­n Ä‘Ãºng sá»‘ tiá»n Ä‘Ã£ náº¡p cá»™ng thÃªm thÆ°á»Ÿng.';
if (!st.enabled) {
note = 'Khuyáº¿n mÃ£i Ä‘ang táº¯t: khÃ¡ch nháº­n Ä‘Ãºng sá»‘ tiá»n Ä‘Ã£ náº¡p (tá»· lá»‡ 1:1).';
