} else {
bonus = Math.round(amt * pct / 100);
if (cap > 0 && bonus > cap) { bonus = cap; note = 'ThÆ°á»Ÿng Ä‘Ã£ cháº¡m má»©c tá»‘i Ä‘a má»—i láº§n.'; }
}
